"use client";

import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  Tooltip,
  ResponsiveContainer,
} from "recharts";

import { Button } from "@/components/ui/button";
import Link from "next/link";
import { Home } from "lucide-react";

interface ChartItem {
  month: string;
  revenue: number;
}

interface DashboardStats {
  revenue: number;
  customers: number;
  orders: number;
  products: number;
  chart: ChartItem[];
}

interface Props {
  stats: DashboardStats;
}

export default function DashboardClient({ stats }: Props) {
  return (
    <div className="space-y-8 p-6">
      <div className="flex items-center justify-between">
        <h1 className="text-3xl font-bold tracking-tight">Dashboard</h1>
        <Link href="/">
          <Button variant="outline" className="flex items-center gap-2">
            <Home className="h-4 w-4" />
            Ke Landing Page
          </Button>
        </Link>
      </div>

      {/* ===== TOP METRIC CARDS ===== */}
      <div className="grid grid-cols-1 gap-6 md:grid-cols-2 lg:grid-cols-4">
        {/* Revenue */}
        <Card className="shadow-sm transition hover:shadow-md">
          <CardHeader className="pb-2">
            <CardTitle className="text-muted-foreground text-sm">
              Total Revenue
            </CardTitle>
          </CardHeader>
          <CardContent className="text-2xl font-bold">
            Rp {stats.revenue.toLocaleString("id-ID")}
          </CardContent>
        </Card>

        {/* Customers */}
        <Card className="shadow-sm transition hover:shadow-md">
          <CardHeader className="pb-2">
            <CardTitle className="text-muted-foreground text-sm">
              Total Customers
            </CardTitle>
          </CardHeader>
          <CardContent className="text-2xl font-bold">
            {stats.customers}
          </CardContent>
        </Card>

        {/* Orders */}
        <Card className="shadow-sm transition hover:shadow-md">
          <CardHeader className="pb-2">
            <CardTitle className="text-muted-foreground text-sm">
              Total Orders
            </CardTitle>
          </CardHeader>
          <CardContent className="text-2xl font-bold">
            {stats.orders}
          </CardContent>
        </Card>

        {/* Products */}
        <Card className="shadow-sm transition hover:shadow-md">
          <CardHeader className="pb-2">
            <CardTitle className="text-muted-foreground text-sm">
              Total Products
            </CardTitle>
          </CardHeader>
          <CardContent className="text-2xl font-bold">
            {stats.products}
          </CardContent>
        </Card>
      </div>

      {/* ===== REVENUE GRAPH ===== */}
      <Card className="shadow-sm">
        <CardHeader>
          <CardTitle className="text-lg font-semibold">Revenue Chart</CardTitle>
        </CardHeader>
        <CardContent className="h-[350px]">
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={stats.chart}>
              <XAxis dataKey="month" stroke="#888" tickLine={false} />
              <YAxis stroke="#888" tickLine={false} />
              <Tooltip
                cursor={{ fill: "#f0f0f0" }}
                formatter={(value: number) =>
                  "Rp " + value.toLocaleString("id-ID")
                }
              />
              <Bar
                dataKey="revenue"
                radius={[6, 6, 0, 0]}
                className="fill-primary"
              />
            </BarChart>
          </ResponsiveContainer>
        </CardContent>
      </Card>
    </div>
  );
}
